def solve(grid):
    """Return the number of islands in a 2D grid of 0s and 1s.
    Islands are groups of orthogonally adjacent 1s.
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if n else 0
    visited = [[False] * m for _ in range(n)]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    islands = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands

