def solve(s: str) -> str:
    n = len(s)
    if n == 0:
        return ''
    start = 0
    max_len = 1
    def expand(l: int, r: int) -> (int, int):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return l+1, r-1
    for i in range(n):
        l, r = expand(i, i)
        cur_len = r - l + 1
        if cur_len > max_len:
            start = l
            max_len = cur_len
        l, r = expand(i, i+1)
        cur_len = r - l + 1
        if cur_len > max_len:
            start = l
            max_len = cur_len
    return s[start:start+max_len]

