def solve(tokens):
    """Evaluate Reverse Polish Notation expressions.
    Supports operators +, -, *, / where division truncates toward zero.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division truncating toward zero
                # Compute truncation toward zero without using float
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                sign = 1 if (a * b) >= 0 else -1
                res = sign * (abs(a) // abs(b))
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

def solve(coins, amount):
    best = [0] + [None] * amount
    for v in range(1, amount + 1):
        opts = [best[v - c] for c in coins if c <= v and best[v - c] is not None]
        best[v] = min(opts) + 1 if opts else None
    return -1 if best[amount] is None else best[amount]

def solve(w, k):
    c = {}
    for x in w:
        c[x] = c.get(x, 0) + 1
    return sorted(c, key=lambda x: (-c[x], x))[:k]

