def solve(meetings):
    """Return the largest number of non‑overlapping meetings.
    A meeting may start exactly when another ends. Zero‑length meetings (where
    start == end) are considered to occupy an instant; therefore only one such
    meeting can be attended at a given time point.
    """
    if not meetings:
        return 0
    # Sort by end time, then by start for deterministic ordering
    meetings = sorted(meetings, key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for start, end in meetings:
        if start == end:
            # Zero‑length meeting: require strict start > last_end
            if start > last_end:
                count += 1
                last_end = end
        else:
            if start >= last_end:
                count += 1
                last_end = end
    return count

