def solve(coins, amount):
    """Return the minimum number of coins needed to make `amount` using unlimited
    coins of given denominations `coins`. If impossible, return -1.
    """
    # DP array where dp[i] is min coins for amount i
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

